mapper.select:
SELECT
    n.id, n.sn_code, n.sku_id, n.batch_number, n.warehouse_id, n.warehouse_area_loca_id,
    n.quality_status, n.entry_order_id, n.outbound_order_id, n.mes_work_order_no, n.status,
    n.create_time, n.create_by, n.update_time, n.update_by,
    w.name AS warehouse_name,
    l.loca_code,
    s.code AS sku_code
FROM wms_item_sn n
LEFT JOIN wms_warehouse w ON w.id = n.warehouse_id
LEFT JOIN wms_warehouse_area_loca l ON l.id = n.warehouse_area_loca_id
LEFT JOIN wms_item_sku s ON s.id = n.sku_id
WHERE n.is_del = 1

    AND n.sn_code LIKE CONCAT('%', #{q.snCode}, '%')


    AND n.sku_id = #{q.skuId}


    AND n.batch_number = #{q.batchNumber}


    AND n.warehouse_id = #{q.warehouseId}


    AND n.warehouse_area_loca_id = #{q.warehouseAreaLocaId}


    AND n.mes_work_order_no = #{q.mesWorkOrderNo}


    AND n.status = #{q.status}


    AND n.entry_order_id = #{q.entryOrderId}


    AND n.outbound_order_id = #{q.outboundOrderId}

ORDER BY n.id DESC
